//! Sprite tables and frame rendering.
//!
//! The pixel data lives in `sprites_data.rs`, generated by `tools/gen-sprites.ts`.

pub use crate::sprites_data::{ACTS, CLEAR, SHEETS};

/// A ride sheet (walk, skate, car, ...): frames before `launch` stand still,
/// frames from `launch` until `outro` move at `speed` sprite pixels per second,
/// `cruise` is the loop played while riding and `outro` onward gets off.
pub struct Sheet {
    pub name: &'static str,
    pub w: usize,
    pub h: usize,
    pub palette: &'static [u32],
    pub frames: &'static [&'static [u8]],
    pub launch: usize,
    pub cruise: &'static [usize],
    pub outro: usize,
    pub speed: f32,
}

/// An act from claude.dev's Lottie set, rasterized onto a 55 by 37 grid.
/// `x`, `y` place the trimmed box on that grid; the bottom row is the floor.
pub struct Act {
    pub name: &'static str,
    pub w: usize,
    pub h: usize,
    pub palette: &'static [u32],
    pub frames: &'static [&'static [u8]],
    pub weight: f32,
    pub x: i32,
    /// Only the tests read it: every act's bottom is the grid floor.
    #[allow(dead_code)]
    pub y: i32,
}

/// Frames play at this rate everywhere.
pub const FPS: u32 = 12;

/// Grid column of Clawd's centre line in the act grid (the `walking` act sits
/// at x = 14 and is 24 wide).
const ACT_CENTER: i32 = 26;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum SpriteRef {
    Sheet(usize),
    Act(usize),
}

/// Which way a drawn frame is turned: upright, or a quarter turn with his
/// feet against the left or the right screen edge.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub enum Rot {
    #[default]
    Upright,
    Left,
    Right,
}

/// Turns a `w` by `h` image so its bottom row lies against the left edge
/// (`Rot::Left`) or the right one; the result is `h` wide and `w` tall.
/// Both are true rotations, never a reflection. Upright copies it.
pub fn rotate(src: &[u32], w: usize, h: usize, rot: Rot, out: &mut Vec<u32>) {
    out.clear();
    if rot == Rot::Upright {
        out.extend_from_slice(src);
        return;
    }
    out.resize(w * h, 0);
    for y in 0..h {
        for x in 0..w {
            let (col, row) = if rot == Rot::Right {
                (y, w - 1 - x)
            } else {
                (h - 1 - y, x)
            };
            out[row * h + col] = src[y * w + x];
        }
    }
}

/// One frame ready to draw.
pub struct Frame {
    pub w: usize,
    pub h: usize,
    pub pixels: &'static [u8],
    pub palette: &'static [u32],
    /// Sprite columns from the left edge to Clawd's centre line.
    pub anchor: i32,
}

pub fn sheet_index(name: &str) -> usize {
    SHEETS
        .iter()
        .position(|s| s.name == name)
        .unwrap_or_else(|| panic!("no sheet {name}"))
}

pub fn act_index(name: &str) -> usize {
    ACTS.iter()
        .position(|a| a.name == name)
        .unwrap_or_else(|| panic!("no act {name}"))
}

pub fn frame_count(r: SpriteRef) -> usize {
    match r {
        SpriteRef::Sheet(i) => SHEETS[i].frames.len(),
        SpriteRef::Act(i) => ACTS[i].frames.len(),
    }
}

pub fn frame(r: SpriteRef, n: usize) -> Frame {
    match r {
        SpriteRef::Sheet(i) => {
            let s = &SHEETS[i];
            Frame {
                w: s.w,
                h: s.h,
                pixels: s.frames[n % s.frames.len()],
                palette: s.palette,
                anchor: (s.w / 2) as i32,
            }
        }
        SpriteRef::Act(i) => {
            let a = &ACTS[i];
            Frame {
                w: a.w,
                h: a.h,
                pixels: a.frames[n % a.frames.len()],
                palette: a.palette,
                anchor: ACT_CENTER - a.x,
            }
        }
    }
}

/// Largest frame size over every sheet and act, in sprite pixels.
pub fn max_size() -> (usize, usize) {
    let w = SHEETS
        .iter()
        .map(|s| s.w)
        .chain(ACTS.iter().map(|a| a.w))
        .max()
        .unwrap_or(1);
    let h = SHEETS
        .iter()
        .map(|s| s.h)
        .chain(ACTS.iter().map(|a| a.h))
        .max()
        .unwrap_or(1);
    (w, h)
}

/// The "?!" a startled Clawd shows, as clawd-buddy says it: dark text in a
/// small light bubble. `#` is text, `o` the bubble, `.` clear.
const MARK: [&str; 7] = [
    ".ooooo.", "o###o#o", "ooo#o#o", "oo##o#o", "ooooooo", "oo#oo#o", ".ooooo.",
];
const MARK_TEXT: u32 = 0x141413;
const MARK_FILL: u32 = 0xf9f8f4;
/// Sprite rows the "?!" adds above a frame: the bubble and one row of gap.
pub const MARK_ROWS: usize = MARK.len() + 1;

/// Adds `MARK_ROWS` sprite rows on top of a rendered image (`w` screen
/// pixels wide, premultiplied BGRA) and draws the "?!" in them, centred on
/// column `cx` and kept inside the image.
pub fn add_mark(buf: &mut Vec<u32>, w: usize, scale: usize, cx: i32) {
    let rows = MARK_ROWS * scale;
    buf.splice(0..0, std::iter::repeat_n(0, w * rows));
    let mw = MARK[0].len() * scale;
    let left = (cx - mw as i32 / 2).clamp(0, w.saturating_sub(mw) as i32) as usize;
    for (sy, row) in MARK.iter().enumerate() {
        for (sx, ch) in row.bytes().enumerate() {
            let c = match ch {
                b'#' => MARK_TEXT,
                b'o' => MARK_FILL,
                _ => continue,
            };
            for yy in 0..scale {
                let base = (sy * scale + yy) * w + left + sx * scale;
                if let Some(px) = buf.get_mut(base..base + scale) {
                    px.fill(0xff00_0000 | c);
                }
            }
        }
    }
}

impl Frame {
    /// Left edge in screen pixels when Clawd's centre line is at `cx`.
    pub fn left(&self, cx: i32, scale: i32, mirrored: bool) -> i32 {
        if mirrored {
            cx - (self.w as i32 - self.anchor) * scale
        } else {
            cx - self.anchor * scale
        }
    }

    /// Renders into a premultiplied BGRA buffer of `w * scale` by `h * scale`
    /// (one u32 per pixel, 0xAARRGGBB). Clear pixels become 0.
    pub fn render(&self, scale: usize, mirrored: bool, out: &mut Vec<u32>) {
        let (ow, oh) = (self.w * scale, self.h * scale);
        out.clear();
        out.resize(ow * oh, 0);
        for sy in 0..self.h {
            let row = &self.pixels[sy * self.w..(sy + 1) * self.w];
            for (sx, &p) in row.iter().enumerate() {
                if p == CLEAR {
                    continue;
                }
                let c = 0xff00_0000 | self.palette[p as usize];
                let dx = if mirrored { self.w - 1 - sx } else { sx };
                for yy in 0..scale {
                    let base = (sy * scale + yy) * ow + dx * scale;
                    out[base..base + scale].fill(c);
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn walk_frame0_size_and_body() {
        let walk = &SHEETS[sheet_index("walk")];
        assert_eq!((walk.w, walk.h), (24, 18));
        let f = walk.frames[0];
        assert_eq!(f.len(), 24 * 18);
        // Top two rows are clear, the arms row 6 spans the full width in orange.
        assert!(f[..48].iter().all(|&p| p == CLEAR));
        for x in 0..24 {
            let p = f[6 * 24 + x];
            assert_ne!(p, CLEAR);
            assert_eq!(walk.palette[p as usize], 0xd97757, "pixel ({x}, 6)");
        }
        // Eyes are the dark palette entry.
        assert_eq!(walk.palette[f[4 * 24 + 6] as usize], 0x141413);
    }

    #[test]
    fn walk_sheet_matches_walking_act() {
        let walk = &SHEETS[sheet_index("walk")];
        let act = &ACTS[act_index("walking")];
        assert_eq!((act.w, act.h), (walk.w, walk.h));
        assert_eq!(act.frames.len(), walk.frames.len());
        for (a, b) in act.frames.iter().zip(walk.frames.iter()) {
            for (pa, pb) in a.iter().zip(b.iter()) {
                let ca = (*pa != CLEAR).then(|| act.palette[*pa as usize]);
                let cb = (*pb != CLEAR).then(|| walk.palette[*pb as usize]);
                assert_eq!(ca, cb);
            }
        }
    }

    #[test]
    fn tables_are_complete() {
        assert_eq!(SHEETS.len(), 8);
        assert_eq!(ACTS.len(), 36);
        assert_eq!(ACTS.iter().filter(|a| a.weight > 0.0).count(), 33);
        for a in ACTS.iter() {
            assert_eq!(a.y + a.h as i32, 37, "{} does not end on the floor", a.name);
            for f in a.frames {
                assert_eq!(f.len(), a.w * a.h);
            }
        }
    }

    #[test]
    fn render_scales_and_mirrors() {
        let fr = frame(SpriteRef::Sheet(sheet_index("walk")), 4);
        let mut a = Vec::new();
        let mut b = Vec::new();
        fr.render(3, false, &mut a);
        fr.render(3, true, &mut b);
        let w = 24 * 3;
        assert_eq!(a.len(), w * 18 * 3);
        for y in 0..18 * 3 {
            for x in 0..w {
                assert_eq!(a[y * w + x], b[y * w + (w - 1 - x)]);
            }
        }
        assert_eq!(fr.left(100, 3, false), 100 - 12 * 3);
    }

    #[test]
    fn rotation_puts_his_feet_on_the_wall() {
        let fr = frame(SpriteRef::Sheet(sheet_index("walk")), 0);
        let mut up = Vec::new();
        fr.render(1, false, &mut up);
        let (w, h) = (fr.w, fr.h);
        let opaque = |b: &[u32], i: usize| b[i] >> 24 != 0;
        for (rot, feet_col) in [(Rot::Right, h - 1), (Rot::Left, 0)] {
            let mut out = Vec::new();
            rotate(&up, w, h, rot, &mut out);
            assert_eq!(out.len(), w * h);
            // His bottom row (feet) becomes the column against the wall.
            let feet = (0..w).filter(|&x| opaque(&up, (h - 1) * w + x)).count();
            let wall = (0..w).filter(|&r| opaque(&out, r * h + feet_col)).count();
            assert_eq!(feet, wall, "{rot:?}");
            // Same pixels, just moved.
            assert_eq!(
                (0..w * h).filter(|&i| opaque(&up, i)).count(),
                (0..w * h).filter(|&i| opaque(&out, i)).count()
            );
        }
        // Left then right is a half turn, not the original.
        let (mut a, mut b) = (Vec::new(), Vec::new());
        rotate(&up, w, h, Rot::Left, &mut a);
        rotate(&a, h, w, Rot::Left, &mut b);
        for y in 0..h {
            for x in 0..w {
                assert_eq!(b[(h - 1 - y) * w + (w - 1 - x)], up[y * w + x]);
            }
        }
    }

    #[test]
    fn mark_sits_above_the_frame_and_fits_the_overlay() {
        let fr = frame(SpriteRef::Sheet(sheet_index("walk")), 0);
        let scale = 2;
        let mut buf = Vec::new();
        fr.render(scale, true, &mut buf);
        let plain = buf.clone();
        let w = fr.w * scale;
        add_mark(&mut buf, w, scale, (fr.w - fr.anchor as usize) as i32 * scale as i32);
        let rows = MARK_ROWS * scale;
        assert_eq!(buf.len(), plain.len() + w * rows);
        // The frame itself is unchanged, just lower.
        assert_eq!(&buf[w * rows..], &plain[..]);
        // Dark text and a light fill, nothing in the gap row.
        assert!(buf[..w * rows].contains(&(0xff00_0000 | MARK_TEXT)));
        assert!(buf[..w * rows].contains(&(0xff00_0000 | MARK_FILL)));
        assert!(buf[w * (rows - scale)..w * rows].iter().all(|&p| p == 0));
        // A walk frame with the mark still fits the overlay window.
        assert!(fr.h + MARK_ROWS <= max_size().1);
    }
}
